    15→package org.hyperledger.besu.ethereum.mainnet.headervalidationrules;
    16→
    17→import org.hyperledger.besu.datatypes.Hash;
    18→import org.hyperledger.besu.ethereum.ProtocolContext;
    19→import org.hyperledger.besu.ethereum.core.BlockHeader;
    20→import org.hyperledger.besu.ethereum.mainnet.AttachedBlockHeaderValidationRule;
    21→
    22→public class ConstantOmmersHashRule implements AttachedBlockHeaderValidationRule {
    23→
    24→  private static final Hash mergeConstant = Hash.EMPTY_LIST_HASH;
    25→
    26→  @Override
    27→  public boolean validate(
    28→      final BlockHeader header, final BlockHeader parent, final ProtocolContext protocolContext) {
    29→    return header.getOmmersHash().equals(mergeConstant);
    30→  }
    31→
    32→  @Override
    33→  public boolean includeInLightValidation() {
    34→    return AttachedBlockHeaderValidationRule.super.includeInLightValidation();
    35→  }
    36→
    37→  @Override
    38→  public String toString() {
    39→    return "ConstantOmmersHash";
    40→  }
    41→}
