    15→package org.hyperledger.besu.ethereum.trie.patricia;
    16→
    17→import org.hyperledger.besu.ethereum.trie.MerkleTrie;
    18→import org.hyperledger.besu.ethereum.trie.PathNodeVisitor;
    19→import org.hyperledger.besu.ethereum.trie.SimpleMerkleTrie;
    20→
    21→import java.util.function.Function;
    22→
    23→import org.apache.tuweni.bytes.Bytes;
    24→
    25→/**
    26→ * An in-memory {@link MerkleTrie}.
    27→ *
    28→ * @param <V> The type of values stored by this trie.
    29→ */
    30→public class SimpleMerklePatriciaTrie<K extends Bytes, V> extends SimpleMerkleTrie<K, V>
    31→    implements MerkleTrie<K, V> {
    32→  private final GetVisitor<V> getVisitor = new GetVisitor<>();
    33→  private final RemoveVisitor<V> removeVisitor = new RemoveVisitor<>();
    34→
    35→  public SimpleMerklePatriciaTrie(final Function<V, Bytes> valueSerializer) {
    36→    super(valueSerializer);
    37→  }
    38→
    39→  @Override
    40→  public GetVisitor<V> getGetVisitor() {
    41→    return getVisitor;
    42→  }
    43→
    44→  @Override
    45→  public RemoveVisitor<V> getRemoveVisitor() {
    46→    return removeVisitor;
    47→  }
    48→
    49→  @Override
    50→  public PathNodeVisitor<V> getPutVisitor(final V value) {
    51→    return new PutVisitor<>(nodeFactory, value);
    52→  }
    53→}
