    15→package org.hyperledger.besu.ethereum.trie;
    16→
    17→import static com.google.common.base.Preconditions.checkArgument;
    18→
    19→import org.apache.tuweni.bytes.Bytes;
    20→import org.apache.tuweni.bytes.MutableBytes;
    21→
    22→public abstract class CompactEncoding {
    23→  private CompactEncoding() {}
    24→
    25→  public static final byte LEAF_TERMINATOR = 0x10;
    26→
    27→  /**
    28→   * Converts a byte sequence into a path by splitting each byte into two nibbles. The resulting
    29→   * path is terminated with a leaf terminator.
    30→   *
    31→   * @param bytes the byte sequence to convert into a path
    32→   * @return the resulting path
    33→   */
    34→  public static Bytes bytesToPath(final Bytes bytes) {
    35→    final MutableBytes path = MutableBytes.create(bytes.size() * 2 + 1);
    36→    int j = 0;
    37→    for (int i = 0; i < bytes.size(); i += 1, j += 2) {
    38→      final byte b = bytes.get(i);
    39→      path.set(j, (byte) ((b >>> 4) & 0x0f));
    40→      path.set(j + 1, (byte) (b & 0x0f));
    41→    }
    42→    path.set(j, LEAF_TERMINATOR);
    43→    return path;
    44→  }
    45→
    46→  /**
    47→   * Converts a path into a byte sequence by combining each pair of nibbles into a byte. The path
    48→   * must be a leaf path, i.e., it must be terminated with a leaf terminator.
    49→   *
    50→   * @param path the path to convert into a byte sequence
    51→   * @return the resulting byte sequence
    52→   * @throws IllegalArgumentException if the path is empty or not a leaf path, or if it contains
    53→   *     elements larger than a nibble
    54→   */
    55→  public static Bytes pathToBytes(final Bytes path) {
    56→    checkArgument(!path.isEmpty(), "Path must not be empty");
    57→    checkArgument(path.get(path.size() - 1) == LEAF_TERMINATOR, "Path must be a leaf path");
    58→    final MutableBytes bytes = MutableBytes.create((path.size() - 1) / 2);
    59→    int bytesPos = 0;
    60→    for (int pathPos = 0; pathPos < path.size() - 1; pathPos += 2, bytesPos += 1) {
    61→      final byte high = path.get(pathPos);
    62→      final byte low = path.get(pathPos + 1);
    63→      if ((high & 0xf0) != 0 || (low & 0xf0) != 0) {
    64→        throw new IllegalArgumentException("Invalid path: contains elements larger than a nibble");
    65→      }
    66→      bytes.set(bytesPos, (byte) (high << 4 | low));
    67→    }
    68→    return bytes;
    69→  }
    70→
    71→  /**
    72→   * Encodes a path into a compact form. The encoding includes a metadata byte that indicates
    73→   * whether the path is a leaf path and whether its length is odd or even.
    74→   *
    75→   * @param path the path to encode
    76→   * @return the encoded path
    77→   * @throws IllegalArgumentException if the path contains elements larger than a nibble
    78→   */
    79→  public static Bytes encode(final Bytes path) {
    80→    int size = path.size();
    81→    final boolean isLeaf = size > 0 && path.get(size - 1) == LEAF_TERMINATOR;
    82→    if (isLeaf) {
    83→      size = size - 1;
    84→    }
    85→
    86→    final MutableBytes encoded = MutableBytes.create((size + 2) / 2);
    87→    int i = 0;
    88→    int j = 0;
    89→
    90→    if (size % 2 == 1) {
    91→      // add first nibble to magic
    92→      final byte high = (byte) (isLeaf ? 0x03 : 0x01);
    93→      final byte low = path.get(i++);
    94→      if ((low & 0xf0) != 0) {
    95→        throw new IllegalArgumentException("Invalid path: contains elements larger than a nibble");
    96→      }
    97→      encoded.set(j++, (byte) (high << 4 | low));
    98→    } else {
    99→      final byte high = (byte) (isLeaf ? 0x02 : 0x00);
   100→      encoded.set(j++, (byte) (high << 4));
   101→    }
   102→
   103→    while (i < size) {
   104→      final byte high = path.get(i++);
   105→      final byte low = path.get(i++);
   106→      if ((high & 0xf0) != 0 || (low & 0xf0) != 0) {
   107→        throw new IllegalArgumentException("Invalid path: contains elements larger than a nibble");
   108→      }
   109→      encoded.set(j++, (byte) (high << 4 | low));
   110→    }
   111→
   112→    return encoded;
   113→  }
   114→
   115→  /**
   116→   * Decodes a path from its compact form. The decoding process takes into account the metadata byte
   117→   * that indicates whether the path is a leaf path and whether its length is odd or even.
   118→   *
   119→   * @param encoded the encoded path to decode
   120→   * @return the decoded path
   121→   * @throws IllegalArgumentException if the encoded path is empty or its metadata byte is invalid
   122→   */
   123→  public static Bytes decode(final Bytes encoded) {
   124→    final int size = encoded.size();
   125→    checkArgument(size > 0);
   126→    final byte metadata = encoded.get(0);
   127→    checkArgument((metadata & 0xc0) == 0, "Invalid compact encoding");
   128→
   129→    final boolean isLeaf = (metadata & 0x20) != 0;
   130→
   131→    final int pathLength = ((size - 1) * 2) + (isLeaf ? 1 : 0);
   132→    final MutableBytes path;
   133→    int i = 0;
   134→
   135→    if ((metadata & 0x10) != 0) {
   136→      // need to use lower nibble of metadata
   137→      path = MutableBytes.create(pathLength + 1);
   138→      path.set(i++, (byte) (metadata & 0x0f));
   139→    } else {
   140→      path = MutableBytes.create(pathLength);
   141→    }
   142→
   143→    for (int j = 1; j < size; j++) {
   144→      final byte b = encoded.get(j);
   145→      path.set(i++, (byte) ((b >>> 4) & 0x0f));
   146→      path.set(i++, (byte) (b & 0x0f));
   147→    }
   148→
   149→    if (isLeaf) {
   150→      path.set(i, LEAF_TERMINATOR);
   151→    }
   152→
   153→    return path;
   154→  }
   155→}
