    17→import static org.hyperledger.besu.crypto.Hash.keccak256;
    18→
    19→import org.hyperledger.besu.ethereum.rlp.BytesValueRLPOutput;
    20→import org.hyperledger.besu.ethereum.rlp.RLP;
    21→import org.hyperledger.besu.ethereum.trie.LocationNodeVisitor;
    22→import org.hyperledger.besu.ethereum.trie.Node;
