    40→
    41→public class BranchNode<V> implements Node<V> {
    42→
    43→  @SuppressWarnings("rawtypes")
    44→  protected static final Node NULL_NODE = NullNode.instance();
    45→
    46→  private final Optional<Bytes> location;
    47→  private final List<Node<V>> children;
    48→  private final Optional<V> value;
    49→  protected final NodeFactory<V> nodeFactory;
    50→  private final Function<V, Bytes> valueSerializer;
    51→  protected WeakReference<Bytes> encodedBytes;
    52→  private SoftReference<Bytes32> hash;
    53→  private boolean dirty = false;
    54→  private boolean needHeal = false;
    55→
    56→  public BranchNode(
    57→      final Bytes location,
    58→      final List<Node<V>> children,
    59→      final Optional<V> value,
    60→      final NodeFactory<V> nodeFactory,
    61→      final Function<V, Bytes> valueSerializer) {
    62→    assert (children.size() == maxChild());
    63→    this.location = Optional.ofNullable(location);
    64→    this.children = children;
    65→    this.value = value;
    66→    this.nodeFactory = nodeFactory;
    67→    this.valueSerializer = valueSerializer;
    68→  }
    69→
    70→  public BranchNode(
    71→      final List<Node<V>> children,
    72→      final Optional<V> value,
    73→      final NodeFactory<V> nodeFactory,
    74→      final Function<V, Bytes> valueSerializer) {
    75→    assert (children.size() == maxChild());
    76→    this.location = Optional.empty();
    77→    this.children = children;
    78→    this.value = value;
    79→    this.nodeFactory = nodeFactory;
    80→    this.valueSerializer = valueSerializer;
    81→  }
    82→
    83→  @Override
    84→  public Node<V> accept(final PathNodeVisitor<V> visitor, final Bytes path) {
    85→    return visitor.visit(this, path);
    86→  }
    87→
    88→  @Override
    89→  public void accept(final NodeVisitor<V> visitor) {
    90→    visitor.visit(this);
    91→  }
    92→
    93→  @Override
    94→  public void accept(final Bytes location, final LocationNodeVisitor<V> visitor) {
    95→    visitor.visit(location, this);
    96→  }
    97→
    98→  @Override
    99→  public Optional<Bytes> getLocation() {
   100→    return location;
   101→  }
   102→
   103→  @Override
   104→  public Bytes getPath() {
   105→    return Bytes.EMPTY;
   106→  }
   107→
   108→  @Override
   109→  public Optional<V> getValue() {
   110→    return value;
   111→  }
   112→
   113→  @Override
   114→  public List<Node<V>> getChildren() {
   115→    return Collections.unmodifiableList(children);
   116→  }
   117→
   118→  public Node<V> child(final byte index) {
   119→    return children.get(index);
   120→  }
   121→
   122→  @Override
   123→  public Bytes getEncodedBytes() {
   124→    if (encodedBytes != null) {
   125→      final Bytes encoded = encodedBytes.get();
   126→      if (encoded != null) {
   127→        return encoded;
   128→      }
   129→    }
   130→    final BytesValueRLPOutput out = new BytesValueRLPOutput();
   131→    out.startList();
   132→    for (int i = 0; i < maxChild(); ++i) {
   133→      out.writeRaw(children.get(i).getEncodedBytesRef());
   134→    }
   135→    if (value.isPresent()) {
   136→      out.writeBytes(valueSerializer.apply(value.get()));
   137→    } else {
   138→      out.writeNull();
   139→    }
   140→    out.endList();
   141→    final Bytes encoded = out.encoded();
   142→    encodedBytes = new WeakReference<>(encoded);
   143→    return encoded;
   144→  }
   145→
   146→  @Override
   147→  public Bytes getEncodedBytesRef() {
   148→    if (isReferencedByHash()) {
   149→      return RLP.encodeOne(getHash());
   150→    } else {
   151→      return getEncodedBytes();
   152→    }
   153→  }
   154→
   155→  @Override
   156→  public Bytes32 getHash() {
   157→    if (hash != null) {
   158→      final Bytes32 hashed = hash.get();
   159→      if (hashed != null) {
   160→        return hashed;
   161→      }
   162→    }
   163→    final Bytes32 hashed = keccak256(getEncodedBytes());
   164→    hash = new SoftReference<>(hashed);
   165→    return hashed;
   166→  }
   167→
   168→  @Override
   169→  public Node<V> replacePath(final Bytes newPath) {
   170→    return nodeFactory.createExtension(newPath, this);
   171→  }
   172→
   173→  public Node<V> replaceChild(final byte index, final Node<V> updatedChild) {
   174→    return replaceChild(index, updatedChild, true);
   175→  }
   176→
   177→  public Node<V> replaceChild(
   178→      final byte index, final Node<V> updatedChild, final boolean allowFlatten) {
   179→    final ArrayList<Node<V>> newChildren = new ArrayList<>(children);
   180→    newChildren.set(index, updatedChild);
   181→
   182→    if (updatedChild == NULL_NODE) {
   183→      if (value.isPresent() && !hasChildren()) {
   184→        return nodeFactory.createLeaf(Bytes.of(index), value.get());
   185→      } else if (value.isEmpty() && allowFlatten) {
   186→        final Optional<Node<V>> flattened = maybeFlatten(newChildren);
   187→        if (flattened.isPresent()) {
   188→          return flattened.get();
   189→        }
   190→      }
   191→    }
   192→
   193→    return nodeFactory.createBranch(newChildren, value);
   194→  }
   195→
   196→  public Node<V> replaceValue(final V value) {
   197→    return nodeFactory.createBranch(children, Optional.of(value));
   198→  }
   199→
   200→  public Node<V> removeValue() {
   201→    return maybeFlatten(children).orElse(nodeFactory.createBranch(children, Optional.empty()));
   202→  }
   203→
   204→  protected boolean hasChildren() {
   205→    for (final Node<V> child : children) {
   206→      if (child != NULL_NODE) {
   207→        return true;
   208→      }
   209→    }
   210→    return false;
   211→  }
   212→
   213→  protected Optional<Node<V>> maybeFlatten(final List<Node<V>> children) {
   214→    final int onlyChildIndex = findOnlyChild(children);
   215→    if (onlyChildIndex >= 0) {
   216→      // replace the path of the only child and return it
   217→      final Node<V> onlyChild = children.get(onlyChildIndex);
   218→      final Bytes onlyChildPath = onlyChild.getPath();
   219→      final MutableBytes completePath = MutableBytes.create(1 + onlyChildPath.size());
   220→      completePath.set(0, (byte) onlyChildIndex);
   221→      onlyChildPath.copyTo(completePath, 1);
   222→      return Optional.of(onlyChild.replacePath(completePath));
   223→    }
   224→    return Optional.empty();
   225→  }
   226→
   227→  private int findOnlyChild(final List<Node<V>> children) {
   228→    int onlyChildIndex = -1;
   229→    assert (children.size() == maxChild());
   230→    for (int i = 0; i < maxChild(); ++i) {
   231→      if (children.get(i) != NULL_NODE) {
   232→        if (onlyChildIndex >= 0) {
   233→          return -1;
   234→        }
   235→        onlyChildIndex = i;
   236→      }
   237→    }
   238→    return onlyChildIndex;
   239→  }
   240→
   241→  @Override
   242→  public String print() {
   243→    final StringBuilder builder = new StringBuilder();
   244→    builder.append("Branch:");
   245→    builder.append("\n\tRef: ").append(getEncodedBytesRef());
   246→    for (int i = 0; i < maxChild(); i++) {
   247→      final Node<V> child = child((byte) i);
   248→      if (!Objects.equals(child, NullNode.instance())) {
   249→        final String branchLabel = "[" + Integer.toHexString(i) + "] ";
   250→        final String childRep = child.print().replaceAll("\n\t", "\n\t\t");
   251→        builder.append("\n\t").append(branchLabel).append(childRep);
   252→      }
   253→    }
   254→    builder.append("\n\tValue: ").append(getValue().map(Object::toString).orElse("empty"));
   255→    return builder.toString();
   256→  }
   257→
   258→  @Override
   259→  public boolean isDirty() {
   260→    return dirty;
   261→  }
   262→
   263→  @Override
   264→  public void markDirty() {
   265→    dirty = true;
   266→  }
   267→
   268→  @Override
   269→  public boolean isHealNeeded() {
   270→    return needHeal;
   271→  }
   272→
   273→  @Override
   274→  public void markHealNeeded() {
   275→    this.needHeal = true;
   276→  }
   277→
   278→  public int maxChild() {
   279→    return 16;
   280→  }
   281→}
