    28→/** Represents a bundle of proofs for a blob, including KZG commitments and proofs. */
    29→public final class BlobProofBundle {
    30→
    31→  private final BlobType blobType;
    32→  private final Blob blob;
    33→  private final KZGCommitment kzgCommitment;
    34→  private final List<KZGProof> kzgProof;
    35→  private final VersionedHash versionedHash;
    36→  private final Bytes blobCells;
    37→
    38→  /**
    39→   * @param blobType the type of the blob
    40→   * @param blob the blob being proven.
    41→   * @param kzgCommitment the KZG commitment for the blob.
    42→   * @param kzgProof the KZG proof for the blob.
    43→   * @param versionedHash the versioned hash of the blob.
    44→   */
    45→  public BlobProofBundle(
    46→      final BlobType blobType,
    47→      final Blob blob,
    48→      final KZGCommitment kzgCommitment,
    49→      final List<KZGProof> kzgProof,
    50→      final VersionedHash versionedHash) {
    51→    checkArgument(kzgCommitment != null, "kzgCommitment must not be empty");
    52→    checkArgument(versionedHash != null, "versionedHash must not be empty");
    53→    checkArgument(blob != null, "blob must not be empty");
    54→    checkArgument(kzgProof != null, "kzgProof must not be empty");
    55→    if (blobType == BlobType.KZG_PROOF && kzgProof.size() != 1) {
    56→      String errorMessage =
    57→          "Invalid kzgProof size for versionId 0, expected 1 but got " + kzgProof.size();
    58→      throw new IllegalArgumentException(errorMessage);
    59→    }
    60→    if (blobType == BlobType.KZG_CELL_PROOFS
    61→        && kzgProof.size() != CKZG4844Helper.CELL_PROOFS_PER_BLOB) {
    62→      String errorMessage =
    63→          "Invalid kzgProof size for versionId 1, expected "
    64→              + CKZG4844Helper.CELL_PROOFS_PER_BLOB
    65→              + " but got "
    66→              + kzgProof.size();
    67→      throw new IllegalArgumentException(errorMessage);
    68→    }
    69→    this.blobType = blobType;
    70→    this.blob = blob;
    71→    this.kzgCommitment = kzgCommitment;
    72→    this.kzgProof = kzgProof;
    73→    this.versionedHash = versionedHash;
    74→    this.blobCells = computeCells(blob, blobType);
    75→  }
    76→
    77→  private Bytes computeCells(final Blob blob, final BlobType blobType) {
    78→    if (blobType == BlobType.KZG_CELL_PROOFS) {
    79→      return CKZG4844Helper.computeCells(blob);
    80→    }
    81→    return null;
    82→  }
    83→
    84→  public BlobType getBlobType() {
    85→    return blobType;
    86→  }
    87→
    88→  public Blob getBlob() {
    89→    return blob;
    90→  }
    91→
    92→  public KZGCommitment getKzgCommitment() {
    93→    return kzgCommitment;
    94→  }
    95→
    96→  public List<KZGProof> getKzgProof() {
    97→    return kzgProof;
    98→  }
    99→
   100→  public VersionedHash getVersionedHash() {
   101→    return versionedHash;
   102→  }
   103→
   104→  public Optional<Bytes> getBlobCellsBytes() {
   105→    return Optional.ofNullable(blobCells);
   106→  }
   107→
   108→  @Override
   109→  public boolean equals(final Object obj) {
   110→    if (obj == this) {
   111→      return true;
   112→    }
   113→    if (obj == null || obj.getClass() != this.getClass()) {
   114→      return false;
   115→    }
   116→    var that = (BlobProofBundle) obj;
   117→    return this.blobType == that.blobType
   118→        && Objects.equals(this.blob, that.blob)
   119→        && Objects.equals(this.kzgCommitment, that.kzgCommitment)
   120→        && Objects.equals(this.kzgProof, that.kzgProof)
   121→        && Objects.equals(this.versionedHash, that.versionedHash);
   122→  }
   123→
   124→  @Override
   125→  public int hashCode() {
   126→    return Objects.hash(blobType, blob, kzgCommitment, kzgProof, versionedHash);
   127→  }
   128→}
