    17→import org.hyperledger.besu.consensus.merge.MergeContext;
    18→import org.hyperledger.besu.datatypes.Hash;
    19→import org.hyperledger.besu.ethereum.ProtocolContext;
    20→import org.hyperledger.besu.ethereum.core.BlockHeader;
    21→import org.hyperledger.besu.ethereum.core.Difficulty;
    22→import org.hyperledger.besu.ethereum.mainnet.AttachedBlockHeaderValidationRule;
    23→
    24→import java.util.Optional;
    25→
    26→import org.slf4j.Logger;
    27→import org.slf4j.LoggerFactory;
    28→
    29→/** The Constant ommers hash rule. */
    30→public class ConstantOmmersHashRule implements AttachedBlockHeaderValidationRule {
    31→
    32→  private static final Hash mergeConstant = Hash.EMPTY_LIST_HASH;
    33→
    34→  private static final Logger LOG = LoggerFactory.getLogger(ConstantOmmersHashRule.class);
    35→
    36→  /** Default constructor. */
    37→  public ConstantOmmersHashRule() {}
    38→
    39→  @Override
    40→  public boolean validate(
    41→      final BlockHeader header, final BlockHeader parent, final ProtocolContext protocolContext) {
    42→    Optional<Difficulty> totalDifficulty =
    43→        protocolContext.getBlockchain().getTotalDifficultyByHash(header.getParentHash());
    44→    if (totalDifficulty.isEmpty()) {
    45→      LOG.warn("unable to get total difficulty, parent {} not found", header.getParentHash());
    46→      return false;
    47→    }
    48→    if (totalDifficulty
    49→        .get()
    50→        .greaterOrEqualThan(
    51→            protocolContext.getConsensusContext(MergeContext.class).getTerminalTotalDifficulty())) {
    52→      return header.getOmmersHash().equals(mergeConstant);
    53→    } else {
    54→      return true;
    55→    }
    56→  }
    57→
    58→  @Override
    59→  public boolean includeInLightValidation() {
    60→    return AttachedBlockHeaderValidationRule.super.includeInLightValidation();
    61→  }
    62→
    63→  @Override
    64→  public String toString() {
    65→    return "MergeConstantOmmersHash";
    66→  }
    67→}
