    38→public class LeafNode<V> implements Node<V> {
    39→  private final Optional<Bytes> location;
    40→  private final Bytes path;
    41→  protected final V value;
    42→  private final NodeFactory<V> nodeFactory;
    43→  protected final Function<V, Bytes> valueSerializer;
    44→  protected WeakReference<Bytes> encodedBytes;
    45→  private SoftReference<Bytes32> hash;
    46→  private boolean dirty = false;
    47→
    48→  public LeafNode(
    49→      final Bytes location,
    50→      final Bytes path,
    51→      final V value,
    52→      final NodeFactory<V> nodeFactory,
    53→      final Function<V, Bytes> valueSerializer) {
    54→    this.location = Optional.ofNullable(location);
    55→    this.path = path;
    56→    this.value = value;
    57→    this.nodeFactory = nodeFactory;
    58→    this.valueSerializer = valueSerializer;
    59→  }
    60→
    61→  public LeafNode(
    62→      final Bytes path,
    63→      final V value,
    64→      final NodeFactory<V> nodeFactory,
    65→      final Function<V, Bytes> valueSerializer) {
    66→    this.location = Optional.empty();
    67→    this.path = path;
    68→    this.value = value;
    69→    this.nodeFactory = nodeFactory;
    70→    this.valueSerializer = valueSerializer;
    71→  }
    72→
    73→  @Override
    74→  public Node<V> accept(final PathNodeVisitor<V> visitor, final Bytes path) {
    75→    return visitor.visit(this, path);
    76→  }
    77→
    78→  @Override
    79→  public void accept(final NodeVisitor<V> visitor) {
    80→    visitor.visit(this);
    81→  }
    82→
    83→  @Override
    84→  public void accept(final Bytes location, final LocationNodeVisitor<V> visitor) {
    85→    visitor.visit(location, this);
    86→  }
    87→
    88→  @Override
    89→  public Optional<Bytes> getLocation() {
    90→    return location;
    91→  }
    92→
    93→  @Override
    94→  public Bytes getPath() {
    95→    return path;
    96→  }
    97→
    98→  @Override
    99→  public Optional<V> getValue() {
   100→    return Optional.of(value);
   101→  }
   102→
   103→  @Override
   104→  public List<Node<V>> getChildren() {
   105→    return Collections.emptyList();
   106→  }
   107→
   108→  @Override
   109→  public Bytes getEncodedBytes() {
   110→    if (encodedBytes != null) {
   111→      final Bytes encoded = encodedBytes.get();
   112→      if (encoded != null) {
   113→        return encoded;
   114→      }
   115→    }
   116→
   117→    final BytesValueRLPOutput out = new BytesValueRLPOutput();
   118→    out.startList();
   119→    out.writeBytes(CompactEncoding.encode(path));
   120→    out.writeBytes(valueSerializer.apply(value));
   121→    out.endList();
   122→    final Bytes encoded = out.encoded();
   123→    encodedBytes = new WeakReference<>(encoded);
   124→    return encoded;
   125→  }
   126→
   127→  @Override
   128→  public Bytes getEncodedBytesRef() {
   129→    if (isReferencedByHash()) {
   130→      return RLP.encodeOne(getHash());
   131→    } else {
   132→      return getEncodedBytes();
   133→    }
   134→  }
   135→
   136→  @Override
   137→  public Bytes32 getHash() {
   138→    if (hash != null) {
   139→      final Bytes32 hashed = hash.get();
   140→      if (hashed != null) {
   141→        return hashed;
   142→      }
   143→    }
   144→    final Bytes32 hashed = keccak256(getEncodedBytes());
   145→    hash = new SoftReference<>(hashed);
   146→    return hashed;
   147→  }
   148→
   149→  @Override
   150→  public Node<V> replacePath(final Bytes path) {
   151→    return nodeFactory.createLeaf(path, value);
   152→  }
   153→
   154→  @Override
   155→  public String print() {
   156→    return "Leaf:"
   157→        + "\n\tRef: "
   158→        + getEncodedBytesRef()
   159→        + "\n\tPath: "
   160→        + CompactEncoding.encode(path)
   161→        + "\n\tValue: "
   162→        + getValue().map(Object::toString).orElse("empty");
   163→  }
   164→
   165→  @Override
   166→  public boolean isDirty() {
   167→    return dirty;
   168→  }
   169→
   170→  @Override
   171→  public void markDirty() {
   172→    dirty = true;
   173→  }
   174→
   175→  @Override
   176→  public boolean isHealNeeded() {
   177→    return false;
   178→  }
   179→
   180→  @Override
   181→  public void markHealNeeded() {
   182→    // nothing to do a leaf don't have child
   183→  }
   184→}
