    15→package org.hyperledger.besu.ethereum.core.kzg;
    16→
    17→import static com.google.common.base.Preconditions.checkArgument;
    18→import static org.hyperledger.besu.datatypes.BlobType.KZG_PROOF;
    19→import static org.hyperledger.besu.ethereum.core.kzg.CKZG4844Helper.CELL_PROOFS_PER_BLOB;
    20→
    21→import org.hyperledger.besu.datatypes.BlobType;
    22→import org.hyperledger.besu.datatypes.VersionedHash;
    23→
    24→import java.security.InvalidParameterException;
    25→import java.util.ArrayList;
    26→import java.util.List;
    27→import java.util.Objects;
    28→import java.util.stream.IntStream;
    29→
    30→import org.apache.tuweni.bytes.Bytes;
    31→
    32→/** A class to hold the blobs, commitments, proofs, and versioned hashes for a set of blobs. */
    33→public class BlobsWithCommitments implements org.hyperledger.besu.datatypes.BlobsWithCommitments {
    34→  private final BlobType blobType;
    35→  private final List<BlobProofBundle> blobProofBundles;
    36→
    37→  /**
    38→   * Constructs a {@link BlobsWithCommitments} instance from a list of {@link BlobProofBundle}.
    39→   *
    40→   * @param blobProofBundles the list of blob proof bundles to be attached to the transaction.
    41→   */
    42→  public BlobsWithCommitments(final List<BlobProofBundle> blobProofBundles) {
    43→    checkArgument(!blobProofBundles.isEmpty(), "BlobProofBundles list cannot be empty");
    44→    BlobType blobType = blobProofBundles.getFirst().getBlobType();
    45→    checkArgument(
    46→        blobProofBundles.stream().allMatch(bundle -> bundle.getBlobType() == blobType),
    47→        "BlobProofBundles must have the same BlobType");
    48→    this.blobProofBundles = blobProofBundles;
    49→    this.blobType = blobType;
    50→  }
    51→
    52→  /**
    53→   * Constructs a {@link BlobsWithCommitments} instance.
    54→   *
    55→   * @param blobType blobType for the sidecar.
    56→   * @param kzgCommitments commitments for the blobs.
    57→   * @param blobs list of blobs to be committed to.
    58→   * @param kzgProofs proofs for the commitments.
    59→   * @param versionedHashes hashes of the commitments.
    60→   * @throws InvalidParameterException if the input parameters are invalid.
    61→   */
    62→  public BlobsWithCommitments(
    63→      final BlobType blobType,
    64→      final List<KZGCommitment> kzgCommitments,
    65→      final List<Blob> blobs,
    66→      final List<KZGProof> kzgProofs,
    67→      final List<VersionedHash> versionedHashes) {
    68→    validateInputParameters(blobType, kzgCommitments, blobs, kzgProofs, versionedHashes);
    69→    this.blobProofBundles =
    70→        buildBlobProofBundles(blobType, kzgCommitments, blobs, kzgProofs, versionedHashes);
    71→    this.blobType = blobType;
    72→  }
    73→
    74→  private static List<BlobProofBundle> buildBlobProofBundles(
    75→      final BlobType blobType,
    76→      final List<KZGCommitment> kzgCommitments,
    77→      final List<Blob> blobs,
    78→      final List<KZGProof> kzgProofs,
    79→      final List<VersionedHash> versionedHashes) {
    80→    return IntStream.range(0, blobs.size())
    81→        .mapToObj(
    82→            index -> {
    83→              List<KZGProof> kzgProofsForBlob = extractProofsForBlob(blobType, kzgProofs, index);
    84→              return new BlobProofBundle(
    85→                  blobType,
    86→                  blobs.get(index),
    87→                  kzgCommitments.get(index),
    88→                  kzgProofsForBlob,
    89→                  versionedHashes.get(index));
    90→            })
    91→        .toList();
    92→  }
    93→
    94→  private static List<KZGProof> extractProofsForBlob(
    95→      final BlobType blobType, final List<KZGProof> kzgProofs, final int index) {
    96→    return switch (blobType) {
    97→      case KZG_PROOF -> List.of(kzgProofs.get(index)); // Single proof per blob
    98→      case KZG_CELL_PROOFS ->
    99→          kzgProofs.subList(
   100→              index * CELL_PROOFS_PER_BLOB,
   101→              (index + 1) * CELL_PROOFS_PER_BLOB); // 128 cell proofs per blob
   102→    };
   103→  }
   104→
   105→  private static void validateInputParameters(
   106→      final BlobType blobType,
   107→      final List<KZGCommitment> kzgCommitments,
   108→      final List<Blob> blobs,
   109→      final List<KZGProof> kzgProofs,
   110→      final List<VersionedHash> versionedHashes) {
   111→    int blobCount = blobs.size();
   112→    int expectedProofs = blobType == KZG_PROOF ? blobCount : CELL_PROOFS_PER_BLOB * blobCount;
   113→    checkArgument(
   114→        blobCount > 0,
   115→        "There needs to be a minimum of one blob in a blob transaction with commitments");
   116→    checkArgument(
   117→        blobCount == kzgCommitments.size(),
   118→        "Invalid number of kzgCommitments, expected %s, got %s",
   119→        blobCount,
   120→        kzgCommitments.size());
   121→    checkArgument(
   122→        blobCount == versionedHashes.size(),
   123→        "Invalid number of versionedHashes, expected %s, got %s",
   124→        blobCount,
   125→        versionedHashes.size());
   126→    checkArgument(
   127→        kzgProofs.size() == expectedProofs,
   128→        "Invalid number of proofs (%s), expected %s, got %s",
   129→        blobType,
   130→        expectedProofs,
   131→        kzgProofs.size());
   132→  }
   133→
   134→  /**
   135→   * Get the blobs.
   136→   *
   137→   * @return the blobs
   138→   */
   139→  @Override
   140→  public List<Blob> getBlobs() {
   141→    return blobProofBundles.stream().map(BlobProofBundle::getBlob).toList();
   142→  }
   143→
   144→  /**
   145→   * Get the commitments.
   146→   *
   147→   * @return the commitments
   148→   */
   149→  @Override
   150→  public List<KZGCommitment> getKzgCommitments() {
   151→    return blobProofBundles.stream().map(BlobProofBundle::getKzgCommitment).toList();
   152→  }
   153→
   154→  /**
   155→   * Get the proofs.
   156→   *
   157→   * @return the proofs
   158→   */
   159→  @Override
   160→  public List<KZGProof> getKzgProofs() {
   161→    return blobProofBundles.stream().flatMap(bundle -> bundle.getKzgProof().stream()).toList();
   162→  }
   163→
   164→  /**
   165→   * Get the hashes.
   166→   *
   167→   * @return the hashes
   168→   */
   169→  @Override
   170→  public List<VersionedHash> getVersionedHashes() {
   171→    return blobProofBundles.stream().map(BlobProofBundle::getVersionedHash).toList();
   172→  }
   173→
   174→  /**
   175→   * Get the list of BlobProofBundle.
   176→   *
   177→   * @return blob proof bundles
   178→   */
   179→  public List<BlobProofBundle> getBlobProofBundles() {
   180→    return blobProofBundles;
   181→  }
   182→
   183→  /**
   184→   * Get the BlobType
   185→   *
   186→   * @return the type of the blobs
   187→   */
   188→  @Override
   189→  public BlobType getBlobType() {
   190→    return blobType;
   191→  }
   192→
   193→  /**
   194→   * Get the KZG proofs as a byte array. Passed to the CKZG4844JNI for proof verification.
   195→   *
   196→   * @return the KZG proofs as a byte array
   197→   */
   198→  byte[] getKzgProofsByteArray() {
   199→    return Bytes.wrap(getKzgProofs().stream().map(kp -> (Bytes) kp.getData()).toList())
   200→        .toArrayUnsafe();
   201→  }
   202→
   203→  /**
   204→   * Get the blobs as a byte array. Passed to the CKZG4844JNI for proof verification.
   205→   *
   206→   * @return the blobs as a byte array
   207→   */
   208→  byte[] getBlobsByteArray() {
   209→    return Bytes.wrap(getBlobs().stream().map(Blob::getData).toList()).toArrayUnsafe();
   210→  }
   211→
   212→  /**
   213→   * Get the KZG commitments as a byte array. Passed to the CKZG4844JNI for proof verification.
   214→   *
   215→   * @return the KZG commitments as a byte array
   216→   */
   217→  byte[] getKzgCommitmentsByteArray() {
   218→    List<KZGCommitment> commitments =
   219→        (blobType == BlobType.KZG_CELL_PROOFS)
   220→            ? extendCommitments(getKzgCommitments())
   221→            : getKzgCommitments();
   222→    return Bytes.wrap(commitments.stream().map(kc -> (Bytes) kc.getData()).toList())
   223→        .toArrayUnsafe();
   224→  }
   225→
   226→  /**
   227→   * Extends the KZG commitments to match the number of cell proofs per blob. This is necessary when
   228→   * the blob type is KZG_CELL_PROOFS, and we want to verify the cell proofs
   229→   *
   230→   * @param commitments the original list of KZG commitments.
   231→   * @return a new list of KZG commitments, extended to match the number of cell proofs per blob.
   232→   */
   233→  private List<KZGCommitment> extendCommitments(final List<KZGCommitment> commitments) {
   234→    int newSize = commitments.size() * CELL_PROOFS_PER_BLOB;
   235→    ArrayList<KZGCommitment> extendedCommitments = new ArrayList<>(newSize);
   236→    for (KZGCommitment kzgCommitment : commitments) {
   237→      for (int i = 0; i < CELL_PROOFS_PER_BLOB; i++) {
   238→        extendedCommitments.add(new KZGCommitment(kzgCommitment.getData()));
   239→      }
   240→    }
   241→    return extendedCommitments;
   242→  }
   243→
   244→  /**
   245→   * Get the blob cells as a byte array. Passed to the CKZG4844JNI for proof verification.
   246→   *
   247→   * @return the blob cells as a byte array
   248→   */
   249→  byte[] getBlobCellsByteArray() {
   250→    return Bytes.wrap(
   251→            blobProofBundles.stream().map(cell -> cell.getBlobCellsBytes().orElseThrow()).toList())
   252→        .toArrayUnsafe();
   253→  }
   254→
   255→  /**
   256→   * Get the cell indexes for the blobs. Passed to the CKZG4844JNI for proof verification.
   257→   *
   258→   * @return an array of cell indexes
   259→   */
   260→  long[] getCellIndexes() {
   261→    long[] cellIndices = new long[CELL_PROOFS_PER_BLOB * blobProofBundles.size()];
   262→    for (int blobIndex = 0; blobIndex < blobProofBundles.size(); blobIndex++) {
   263→      for (int index = 0; index < CELL_PROOFS_PER_BLOB; index++) {
   264→        cellIndices[blobIndex * CELL_PROOFS_PER_BLOB + index] = index;
   265→      }
   266→    }
   267→    return cellIndices;
   268→  }
   269→
   270→  @Override
   271→  public boolean equals(final Object o) {
   272→    if (this == o) return true;
   273→    if (o == null || getClass() != o.getClass()) return false;
   274→    BlobsWithCommitments that = (BlobsWithCommitments) o;
   275→    return blobType == that.blobType && Objects.equals(blobProofBundles, that.blobProofBundles);
   276→  }
   277→
   278→  @Override
   279→  public int hashCode() {
   280→    return Objects.hash(blobProofBundles, blobType);
   281→  }
   282→}
