    24→/** This class contains the data for a KZG commitment. */
    25→public class KZGCommitment implements org.hyperledger.besu.datatypes.KZGCommitment {
    26→  private final Bytes48 data;
    27→
    28→  /**
    29→   * Constructor for a KZG commitment.
    30→   *
    31→   * @param data The data for the KZG commitment.
    32→   */
    33→  public KZGCommitment(final Bytes48 data) {
    34→    this.data = data;
    35→  }
    36→
    37→  /**
    38→   * Reads a KZG commitment from the RLP input.
    39→   *
    40→   * @param input The RLP input.
    41→   * @return The KZG commitment.
    42→   */
    43→  public static KZGCommitment readFrom(final RLPInput input) {
    44→    final Bytes48 bytes = input.readBytes48();
    45→    return new KZGCommitment(bytes);
    46→  }
    47→
    48→  /**
    49→   * Writes the KZG commitment to the RLP output.
    50→   *
    51→   * @param out The RLP output.
    52→   */
    53→  public void writeTo(final RLPOutput out) {
    54→    out.writeBytes(data);
    55→  }
    56→
    57→  /**
    58→   * Gets the data for the KZG commitment.
    59→   *
    60→   * @return The data for the KZG commitment.
    61→   */
    62→  @Override
    63→  public Bytes48 getData() {
    64→    return data;
    65→  }
    66→
    67→  @Override
    68→  public boolean equals(final Object o) {
    69→    if (this == o) return true;
    70→    if (o == null || getClass() != o.getClass()) return false;
    71→    KZGCommitment that = (KZGCommitment) o;
    72→    return Objects.equals(getData(), that.getData());
    73→  }
    74→
    75→  @Override
    76→  public int hashCode() {
    77→    return Objects.hash(getData());
    78→  }
    79→}
