    15→package org.hyperledger.besu.ethereum.trie.patricia;
    16→
    17→import static org.hyperledger.besu.crypto.Hash.keccak256;
    18→
    19→import org.hyperledger.besu.ethereum.rlp.BytesValueRLPOutput;
    20→import org.hyperledger.besu.ethereum.rlp.RLP;
    21→import org.hyperledger.besu.ethereum.trie.CompactEncoding;
    22→import org.hyperledger.besu.ethereum.trie.LocationNodeVisitor;
    23→import org.hyperledger.besu.ethereum.trie.Node;
    24→import org.hyperledger.besu.ethereum.trie.NodeFactory;
    25→import org.hyperledger.besu.ethereum.trie.NodeVisitor;
    26→import org.hyperledger.besu.ethereum.trie.PathNodeVisitor;
    27→
    28→import java.lang.ref.SoftReference;
    29→import java.lang.ref.WeakReference;
    30→import java.util.Collections;
    31→import java.util.List;
    32→import java.util.Optional;
    33→
    34→import org.apache.tuweni.bytes.Bytes;
    35→import org.apache.tuweni.bytes.Bytes32;
    36→
    37→public class ExtensionNode<V> implements Node<V> {
    38→
    39→  private final Optional<Bytes> location;
    40→  private final Bytes path;
    41→  private final Node<V> child;
    42→  private final NodeFactory<V> nodeFactory;
    43→  private WeakReference<Bytes> rlp;
    44→  private SoftReference<Bytes32> hash;
    45→  private boolean dirty = false;
    46→  private boolean needHeal = false;
    47→
    48→  public ExtensionNode(
    49→      final Bytes location,
    50→      final Bytes path,
    51→      final Node<V> child,
    52→      final NodeFactory<V> nodeFactory) {
    53→    assert (path.size() > 0);
    54→    assert (path.get(path.size() - 1) != CompactEncoding.LEAF_TERMINATOR)
    55→        : "Extension path ends in a leaf terminator";
    56→    this.location = Optional.ofNullable(location);
    57→    this.path = path;
    58→    this.child = child;
    59→    this.nodeFactory = nodeFactory;
    60→  }
    61→
    62→  public ExtensionNode(final Bytes path, final Node<V> child, final NodeFactory<V> nodeFactory) {
    63→    assert (path.size() > 0);
    64→    assert (path.get(path.size() - 1) != CompactEncoding.LEAF_TERMINATOR)
    65→        : "Extension path ends in a leaf terminator";
    66→    this.location = Optional.empty();
    67→    this.path = path;
    68→    this.child = child;
    69→    this.nodeFactory = nodeFactory;
    70→  }
    71→
    72→  @Override
    73→  public Node<V> accept(final PathNodeVisitor<V> visitor, final Bytes path) {
    74→    return visitor.visit(this, path);
    75→  }
    76→
    77→  @Override
    78→  public void accept(final NodeVisitor<V> visitor) {
    79→    visitor.visit(this);
    80→  }
    81→
    82→  @Override
    83→  public void accept(final Bytes location, final LocationNodeVisitor<V> visitor) {
    84→    visitor.visit(location, this);
    85→  }
    86→
    87→  @Override
    88→  public Optional<Bytes> getLocation() {
    89→    return location;
    90→  }
    91→
    92→  @Override
    93→  public Bytes getPath() {
    94→    return path;
    95→  }
    96→
    97→  @Override
    98→  public Optional<V> getValue() {
    99→    return Optional.empty();
   100→  }
   101→
   102→  @Override
   103→  public List<Node<V>> getChildren() {
   104→    return Collections.singletonList(child);
   105→  }
   106→
   107→  public Node<V> getChild() {
   108→    return child;
   109→  }
   110→
   111→  @Override
   112→  public Bytes getEncodedBytes() {
   113→    if (rlp != null) {
   114→      final Bytes encoded = rlp.get();
   115→      if (encoded != null) {
   116→        return encoded;
   117→      }
   118→    }
   119→    final BytesValueRLPOutput out = new BytesValueRLPOutput();
   120→    out.startList();
   121→    out.writeBytes(CompactEncoding.encode(path));
   122→    out.writeRaw(child.getEncodedBytesRef());
   123→    out.endList();
   124→    final Bytes encoded = out.encoded();
   125→    rlp = new WeakReference<>(encoded);
   126→    return encoded;
   127→  }
   128→
   129→  @Override
   130→  public Bytes getEncodedBytesRef() {
   131→    if (isReferencedByHash()) {
   132→      return RLP.encodeOne(getHash());
   133→    } else {
   134→      return getEncodedBytes();
   135→    }
   136→  }
   137→
   138→  @Override
   139→  public Bytes32 getHash() {
   140→    if (hash != null) {
   141→      final Bytes32 hashed = hash.get();
   142→      if (hashed != null) {
   143→        return hashed;
   144→      }
   145→    }
   146→    final Bytes rlp = getEncodedBytes();
   147→    final Bytes32 hashed = keccak256(rlp);
   148→    hash = new SoftReference<>(hashed);
   149→    return hashed;
   150→  }
   151→
   152→  public Node<V> replaceChild(final Node<V> updatedChild) {
   153→    // collapse this extension - if the child is a branch, it will create a new extension
   154→    return updatedChild.replacePath(Bytes.concatenate(path, updatedChild.getPath()));
   155→  }
   156→
   157→  @Override
   158→  public Node<V> replacePath(final Bytes path) {
   159→    if (path.size() == 0) {
   160→      return child;
   161→    }
   162→    return nodeFactory.createExtension(path, child);
   163→  }
   164→
   165→  @Override
   166→  public String print() {
   167→    final StringBuilder builder = new StringBuilder();
   168→    final String childRep = getChild().print().replaceAll("\n\t", "\n\t\t");
   169→    builder
   170→        .append("Extension:")
   171→        .append("\n\tRef: ")
   172→        .append(getEncodedBytesRef())
   173→        .append("\n\tPath: ")
   174→        .append(CompactEncoding.encode(path))
   175→        .append("\n\t")
   176→        .append(childRep);
   177→    return builder.toString();
   178→  }
   179→
   180→  @Override
   181→  public boolean isDirty() {
   182→    return dirty;
   183→  }
   184→
   185→  @Override
   186→  public void markDirty() {
   187→    dirty = true;
   188→  }
   189→
   190→  @Override
   191→  public boolean isHealNeeded() {
   192→    return needHeal;
   193→  }
   194→
   195→  @Override
   196→  public void markHealNeeded() {
   197→    this.needHeal = true;
   198→  }
   199→}
