    38→/** The KZGPointEval precompile contract. */
    39→public class KZGPointEvalPrecompiledContract implements PrecompiledContract {
    40→  private static final AtomicBoolean loaded = new AtomicBoolean(false);
    41→
    42→  private static final String PRECOMPILE_NAME = "KZGPointEval";
    43→  private static final Cache<Integer, PrecompileInputResultTuple> kzgCache =
    44→      Caffeine.newBuilder().maximumSize(1000).build();
    45→
    46→  /** Default result caching to false unless otherwise set. */
    47→  protected static Boolean enableResultCaching = Boolean.FALSE;
    48→
    49→  private static final Logger LOG = LoggerFactory.getLogger(KZGPointEvalPrecompiledContract.class);
    50→
    51→  private static Bytes successResult;
    52→
    53→  private static void loadLib() {
    54→    CKZG4844JNI.loadNativeLibrary();
    55→    Bytes fieldElementsPerBlob =
    56→        Bytes32.wrap(Words.intBytes(CKZG4844JNI.FIELD_ELEMENTS_PER_BLOB).xor(Bytes32.ZERO));
    57→    Bytes blsModulus =
    58→        Bytes32.wrap(Bytes.of(CKZG4844JNI.BLS_MODULUS.toByteArray()).xor(Bytes32.ZERO));
    59→
    60→    successResult = Bytes.concatenate(fieldElementsPerBlob, blsModulus);
    61→  }
    62→
    63→  /**
    64→   * Init the C-KZG native lib using a file as trusted setup
    65→   *
    66→   * @param trustedSetupFile the file with the trusted setup
    67→   * @throws IllegalStateException is the trusted setup was already loaded
    68→   */
    69→  public static void init(final Path trustedSetupFile) {
    70→    if (loaded.compareAndSet(false, true)) {
    71→      loadLib();
    72→      final String trustedSetupResourceName = trustedSetupFile.toAbsolutePath().toString();
    73→      LOG.info("Loading trusted setup from user-specified resource {}", trustedSetupResourceName);
    74→      CKZG4844JNI.loadTrustedSetup(trustedSetupResourceName, 0);
    75→    } else {
    76→      throw new IllegalStateException("KZG trusted setup was already loaded");
    77→    }
    78→  }
    79→
    80→  /**
    81→   * Init the C-KZG native lib using mainnet trusted setup
    82→   *
    83→   * @throws IllegalStateException is the trusted setup was already loaded
    84→   */
    85→  public static void init() {
    86→    if (loaded.compareAndSet(false, true)) {
    87→      loadLib();
    88→      final String trustedSetupResourceName = "/kzg-trusted-setups/mainnet.txt";
    89→      LOG.info(
    90→          "Loading network trusted setup from classpath resource {}", trustedSetupResourceName);
    91→      CKZG4844JNI.loadTrustedSetupFromResource(
    92→          trustedSetupResourceName, KZGPointEvalPrecompiledContract.class, 0);
    93→    }
    94→  }
    95→
    96→  /** free up resources. */
    97→  @VisibleForTesting
    98→  public static void tearDown() {
    99→    CKZG4844JNI.freeTrustedSetup();
   100→    loaded.set(false);
   101→  }
   102→
   103→  /**
   104→   * Enable or disable precompile result caching.
   105→   *
   106→   * @param enablePrecompileCaching boolean indicating whether to cache precompile results
   107→   */
   108→  public static void setPrecompileCaching(final boolean enablePrecompileCaching) {
   109→    enableResultCaching = enablePrecompileCaching;
   110→  }
   111→
   112→  /** Default constructor. */
   113→  KZGPointEvalPrecompiledContract() {}
   114→
   115→  @Override
   116→  public String getName() {
   117→    return "KZG_POINT_EVALUATION";
   118→  }
   119→
   120→  @Override
   121→  public long gasRequirement(final Bytes input) {
   122→    // As defined in EIP-4844
   123→    return 50000;
   124→  }
   125→
   126→  @NotNull
   127→  @Override
   128→  public PrecompileContractResult computePrecompile(
   129→      final Bytes input, @NotNull final MessageFrame messageFrame) {
   130→
   131→    if (input.size() != 192) {
   132→      return PrecompileContractResult.halt(
   133→          null, Optional.of(ExceptionalHaltReason.PRECOMPILE_ERROR));
   134→    }
   135→
   136→    PrecompileInputResultTuple res;
   137→    Integer cacheKey = null;
   138→
   139→    if (enableResultCaching) {
   140→      cacheKey = AbstractPrecompiledContract.getCacheKey(input);
   141→      res = kzgCache.getIfPresent(cacheKey);
   142→      if (res != null) {
   143→        if (res.cachedInput().equals(input)) {
   144→          cacheEventConsumer.accept(
   145→              new AbstractPrecompiledContract.CacheEvent(
   146→                  PRECOMPILE_NAME, AbstractPrecompiledContract.CacheMetric.HIT));
   147→          return res.cachedResult();
   148→        } else {
   149→          LOG.debug(
   150→              "false positive kzgPointEval {}, cache key {}, cached input: {}, input: {}",
   151→              input.getClass().getSimpleName(),
   152→              cacheKey,
   153→              res.cachedInput().toHexString(),
   154→              input.toHexString());
   155→
   156→          cacheEventConsumer.accept(
   157→              new AbstractPrecompiledContract.CacheEvent(
   158→                  PRECOMPILE_NAME, AbstractPrecompiledContract.CacheMetric.FALSE_POSITIVE));
   159→        }
   160→      } else {
   161→        cacheEventConsumer.accept(
   162→            new AbstractPrecompiledContract.CacheEvent(
   163→                PRECOMPILE_NAME, AbstractPrecompiledContract.CacheMetric.MISS));
   164→      }
   165→    }
   166→
   167→    Bytes32 versionedHash = Bytes32.wrap(input.slice(0, 32));
   168→    Bytes z = input.slice(32, 32);
   169→    Bytes y = input.slice(64, 32);
   170→    Bytes commitment = input.slice(96, 48);
   171→    Bytes proof = input.slice(144, 48);
   172→    if (versionedHash.get(0) != 0x01) { // unsupported hash version
   173→      return PrecompileContractResult.halt(
   174→          null, Optional.of(ExceptionalHaltReason.PRECOMPILE_ERROR));
   175→    } else {
   176→      byte[] hash = Hash.sha256(commitment).toArrayUnsafe();
   177→      hash[0] = 0x01;
   178→      if (!versionedHash.equals(Bytes32.wrap(hash))) {
   179→        return PrecompileContractResult.halt(
   180→            null, Optional.of(ExceptionalHaltReason.PRECOMPILE_ERROR));
   181→      }
   182→    }
   183→    try {
   184→      boolean proved =
   185→          CKZG4844JNI.verifyKzgProof(
   186→              commitment.toArray(), z.toArray(), y.toArray(), proof.toArray());
   187→
   188→      if (proved) {
   189→        res =
   190→            new PrecompileInputResultTuple(
   191→                enableResultCaching ? input.copy() : input,
   192→                PrecompileContractResult.success(successResult));
   193→      } else {
   194→        res =
   195→            new PrecompileInputResultTuple(
   196→                enableResultCaching ? input.copy() : input,
   197→                PrecompileContractResult.halt(
   198→                    null, Optional.of(ExceptionalHaltReason.PRECOMPILE_ERROR)));
   199→      }
   200→      if (cacheKey != null) {
   201→        kzgCache.put(cacheKey, res);
   202→      }
   203→      return res.cachedResult();
   204→    } catch (RuntimeException kzgFailed) {
   205→      LOG.debug("Native KZG failed", kzgFailed);
   206→      res =
   207→          new PrecompileInputResultTuple(
   208→              enableResultCaching ? input.copy() : input,
   209→              PrecompileContractResult.halt(
   210→                  null, Optional.of(ExceptionalHaltReason.PRECOMPILE_ERROR)));
   211→      if (cacheKey != null) {
   212→        kzgCache.put(cacheKey, res);
   213→      }
   214→      return res.cachedResult();
   215→    }
   216→  }
   217→}
