    24→public class RemoveVisitor<V> implements PathNodeVisitor<V> {
    25→  private final Node<V> NULL_NODE_RESULT = NullNode.instance();
    26→
    27→  private final boolean allowFlatten;
    28→
    29→  public RemoveVisitor() {
    30→    allowFlatten = true;
    31→  }
    32→
    33→  public RemoveVisitor(final boolean allowFlatten) {
    34→    this.allowFlatten = allowFlatten;
    35→  }
    36→
    37→  @Override
    38→  public Node<V> visit(final ExtensionNode<V> extensionNode, final Bytes path) {
    39→    final Bytes extensionPath = extensionNode.getPath();
    40→    final int commonPathLength = extensionPath.commonPrefixLength(path);
    41→    assert commonPathLength < path.size()
    42→        : "Visiting path doesn't end with a non-matching terminator";
    43→
    44→    if (commonPathLength == extensionPath.size()) {
    45→      final Node<V> newChild = extensionNode.getChild().accept(this, path.slice(commonPathLength));
    46→      return extensionNode.replaceChild(newChild);
    47→    }
    48→
    49→    // path diverges before the end of the extension, so it cannot match
    50→
    51→    return extensionNode;
    52→  }
    53→
    54→  @Override
    55→  public Node<V> visit(final BranchNode<V> branchNode, final Bytes path) {
    56→    assert path.size() > 0 : "Visiting path doesn't end with a non-matching terminator";
    57→
    58→    final byte childIndex = path.get(0);
    59→    if (childIndex == CompactEncoding.LEAF_TERMINATOR) {
    60→      return branchNode.removeValue();
    61→    }
    62→
    63→    final Node<V> updatedChild = branchNode.child(childIndex).accept(this, path.slice(1));
    64→    return branchNode.replaceChild(childIndex, updatedChild, allowFlatten);
    65→  }
    66→
    67→  @Override
    68→  public Node<V> visit(final LeafNode<V> leafNode, final Bytes path) {
    69→    final Bytes leafPath = leafNode.getPath();
    70→    final int commonPathLength = leafPath.commonPrefixLength(path);
    71→    return (commonPathLength == leafPath.size()) ? NULL_NODE_RESULT : leafNode;
    72→  }
    73→
    74→  @Override
    75→  public Node<V> visit(final NullNode<V> nullNode, final Bytes path) {
    76→    return NULL_NODE_RESULT;
    77→  }
    78→}
